select request_id
  from batch.trigger_request
 where tenant_id = #{tenantId}
   and workflow_definition_id = #{workflowDefinitionId}
   and trigger_type = 'EVENT'
   and external_event_code = #{eventCode}
   and biz_date = #{bizDate}
   and request_status = 'LAUNCHED'
 order by created_at, id
 limit 1

select *
from batch.trigger_request
where tenant_id = #{tenantId}
  and dedup_key = #{dedupKey}
  and trigger_type = 'CATCH_UP'
  and parent_workflow_run_id is null

select exists (
    select 1
    from batch.workflow_run wr
    join batch.workflow_node_run node_run
      on node_run.workflow_run_id = wr.id
     and node_run.node_code = #{parentNodeCode}
     and node_run.node_type = 'JOB'
    where wr.tenant_id = #{tenantId}
      and wr.id = #{parentWorkflowRunId}
      and #{frozenWorkflowSnapshot}
      and (node_run.node_status in ('READY', 'RUNNING')
           or node_run.job_instance_id = #{existingChildJobInstanceId,jdbcType=BIGINT})
      and (node_run.job_instance_id is null
           or node_run.job_instance_id = #{existingChildJobInstanceId,jdbcType=BIGINT})
)

mapper.insert:
insert into batch.trigger_request (
    tenant_id, request_id, trigger_type, job_code, workflow_definition_id, biz_date, dedup_key,
    request_status, trace_id, dry_run, external_event_code, launch_payload
) select
    #{tenantId}, #{requestId}, #{triggerType}, #{jobCode}, #{workflowDefinitionId}, #{bizDate}, #{dedupKey},
    #{requestStatus}, #{traceId},

        #{dryRun}
    false
    , #{externalEventCode}, cast(#{launchPayload,jdbcType=VARCHAR} as jsonb)
where (cast(#{workflowDefinitionId,jdbcType=BIGINT} as bigint) is null or exists (
    select 1 from batch.workflow_definition workflow_definition
    where workflow_definition.tenant_id = #{tenantId}
      and workflow_definition.id = #{workflowDefinitionId}
))
  and (cast(#{parentWorkflowRunId,jdbcType=BIGINT} as bigint) is null or exists (
    select 1 from batch.workflow_run workflow_run
    where workflow_run.tenant_id = #{tenantId}
      and workflow_run.id = #{parentWorkflowRunId}
))
on conflict (tenant_id, request_id) do nothing

mapper.update:
update batch.trigger_request
set request_status = #{requestStatus},
    related_job_instance_id = #{relatedJobInstanceId,jdbcType=BIGINT},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and request_id = #{requestId}
  and (
    request_status not in

        #{protectedStatus}

    or (
      request_status = #{launchedStatus}
      and #{requestStatus} = #{launchedStatus}
      and related_job_instance_id is null
      and #{relatedJobInstanceId,jdbcType=BIGINT} is not null
    )
  )

  and exists (
    select 1 from batch.job_instance job_instance
    where job_instance.tenant_id = #{tenantId}
      and job_instance.id = #{relatedJobInstanceId,jdbcType=BIGINT}
  )

update batch.trigger_request
set trigger_type = #{triggerType},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and request_id = #{requestId}
  and trigger_type = #{expectedTriggerType}

update batch.trigger_request
set request_status = #{targetStatus},
    related_job_instance_id = #{jobInstanceId},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and request_id = #{requestId}
  and request_status in

      #{expectedStatus}



          and related_job_instance_id is null


          and (related_job_instance_id is null or related_job_instance_id = #{jobInstanceId})


  and exists (
      select 1 from batch.job_instance job_instance
      where job_instance.tenant_id = #{tenantId}
        and job_instance.id = #{jobInstanceId,jdbcType=BIGINT}
  )
